<?php use MeatinOS\Core\Csrf; $entityLabels=['shareholder'=>'Partner']; ?>
<div class="module-toolbar card-panel"><div><p class="eyebrow">Controlled files</p><h2>Document Management</h2><p>Permission-protected certificates, manuals, employee, vendor, customer, vehicle, compliance and transaction documents.</p></div><?php if($canManage): ?><button class="btn btn-danger" data-bs-toggle="modal" data-bs-target="#documentModal"><i class="bi bi-cloud-arrow-up me-1"></i>Upload document</button><?php endif; ?></div>
<div class="card-panel table-panel"><div class="table-responsive"><table class="table data-table align-middle"><thead><tr><th>Document</th><th>Entity</th><th>Category</th><th>Access</th><th>Size</th><th>Expiry</th><th>Uploaded</th><th></th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="8"><div class="table-empty"><i class="bi bi-folder2-open"></i><strong>No documents uploaded</strong><span>Add the first controlled company or transaction document.</span></div></td></tr><?php endif; ?><?php foreach($rows as $row): ?><tr><td><div class="record-primary"><span class="record-icon"><i class="bi bi-file-earmark-lock"></i></span><span><strong><?= e($row['title']) ?></strong><small class="d-block text-secondary"><?= e($row['document_number']) ?></small></span></div></td><td><?= e($entityLabels[$row['entity_type']] ?? human_status($row['entity_type'])) ?> #<?= e($row['entity_id']) ?></td><td><?= e($row['category']) ?></td><td><span class="badge rounded-pill text-bg-secondary"><?= e(human_status($row['access_level'])) ?></span></td><td><?= e(number_format((int)$row['file_size']/1024,1)) ?> KB</td><td><?= $row['expiry_date'] ? e(date('j M Y',strtotime($row['expiry_date']))) : '—' ?></td><td><?= e($row['uploaded_by_name'] ?: 'System') ?><small class="d-block text-secondary"><?= e(date('j M Y, g:i A',strtotime($row['created_at']))) ?></small></td><td><a class="btn btn-sm btn-light border" href="<?= e(url('documents.download',['id'=>$row['id']])) ?>"><i class="bi bi-download"></i></a></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php if($canManage): ?><div class="modal fade" id="documentModal" tabindex="-1" aria-hidden="true" data-auto-open="<?= $prefillType && $prefillId ? 'true' : 'false' ?>"><div class="modal-dialog modal-lg modal-dialog-scrollable"><form class="modal-content" method="post" action="<?= e(url('documents.upload')) ?>" enctype="multipart/form-data"><?= Csrf::field() ?><div class="modal-header"><div><p class="eyebrow mb-1">Secure file intake</p><h2 class="modal-title fs-4">Upload document or evidence photo</h2></div><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-6"><label class="form-label">Title *</label><input class="form-control" name="title" maxlength="200" required></div><div class="col-md-6"><label class="form-label">Category *</label><input class="form-control" name="category" maxlength="100" placeholder="POD photo, QC certificate, KYC..." required></div><div class="col-md-4"><label class="form-label">Entity type *</label><select class="form-select" name="entity_type" required><?php foreach($entityOptions as $type=>$label): ?><option value="<?= e($type) ?>" <?= $prefillType===$type?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Entity record ID *</label><input class="form-control" name="entity_id" type="number" min="1" value="<?= e($prefillId ?: 1) ?>" required></div><div class="col-md-4"><label class="form-label">Access *</label><select class="form-select" name="access_level"><option value="private">Private</option><option value="department">Department</option><option value="plant">Plant</option><option value="company">Company</option><option value="customer">Customer</option></select></div><div class="col-md-6"><label class="form-label">Expiry date</label><input class="form-control" name="expiry_date" type="date"></div><div class="col-md-6"><label class="form-label">Tags</label><input class="form-control" name="tags" maxlength="500" placeholder="pod, logistics, entrance, inventory"></div><div class="col-12"><label class="form-label">File *</label><input class="form-control" name="document" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp,.docx,.xlsx,.csv" required><div class="form-text">Maximum 10 MB. Files are kept outside the public web root and MIME-verified server-side.</div></div></div></div><div class="modal-footer"><button class="btn btn-light border" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-danger" type="submit">Upload securely</button></div></form></div></div><?php endif; ?>
